from itertools import combinations


def _route_solver(exact, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        visit = {node: sum(1 << i for i, name in enumerate(required) if name == node)
                 for node in set(required)}
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = visit.get(source, 0)
        initial_remaining = data["coupons"]
        start = data["start"]
        initial = (source, initial_mask, initial_remaining)
        best = {initial: start}
        queue = [(start, source, initial_mask, initial_remaining)]

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if best.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and (not exact or remaining == 0):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    discounted = max(minimum_duration,
                                     edge["duration"] - edge.get("discount", 0))
                    durations.append((discounted, remaining - 1))
                for duration, next_remaining in durations:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | visit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                               next_mask, next_remaining))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator, denominator=10000):
        if half_up:
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}

    def dependencies(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature", "")
            if not feature or feature in features:
                yield dep

    best_vector = None
    best_install = None
    choices = [[None] + sorted(rows[name], reverse=True) for name in names]
    for assignment_values in __import__("itertools").product(*choices):
        assignment = dict(zip(names, assignment_values))
        valid = True
        for name, bounds in roots.items():
            version = assignment.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in names if assignment[name] is not None}
        for name, version in assignment.items():
            if version is None:
                continue
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
            for dep in dependencies(rows[name][version]):
                other = dep["name"]
                other_version = assignment[other]
                if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        visiting, visited = set(), set()

        def acyclic(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in graph[name]):
                return False
            visiting.remove(name)
            visited.add(name)
            return True

        if not all(acyclic(name) for name in graph):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = assignment[name]
            for dep in dependencies(rows[name][version]):
                stack.append(dep["name"])
        if any(assignment[name] is not None and name not in reachable for name in names):
            continue

        vector = tuple(-1 if assignment[name] is None else assignment[name]
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_install = {name: assignment[name] for name in names
                            if assignment[name] is not None}

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for selected in combinations(options, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        feasible = True
        for job in sorted(selected, key=lambda item: item["start"]):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        selected_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids > best_ids)):
            best_value = value
            best_ids = selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


